import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import net from 'node:net';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { setTimeout as delay } from 'node:timers/promises';

const root = 'D:/ClaudeProjects/ai_acknowladge';
const sourcePath = fileURLToPath(import.meta.url);
const source = fs.readFileSync(sourcePath, 'utf8');
const livePath = sourcePath.replace(/\.mjs$/, '.live.json');
const sha = value => crypto.createHash('sha256').update(value).digest('hex');
const relative = value => path.relative(root, value).replaceAll('\\', '/');
const decode = value => value.filter(byte => byte === 0).length > value.length / 4 ? value.toString('utf16le') : value.toString('utf8');
const priorPath = path.join(root, 'docs/验收证据/story-2-2-chronyd-maintenance-2026-09-12T08-47-30-618Z.json');
const prior = JSON.parse(fs.readFileSync(priorPath, 'utf8'));
const report = {
  story: '2.2', recorded_at: new Date().toISOString(), status: 'failed',
  authorization: '用户已确认一次受控 WSL/Engine 停止与恢复，保存终端工作后延续已批准的 A2 维护。',
  scope: '正常停止 Docker Desktop，关闭一次 WSL，再恢复原 Docker Desktop 与 Ubuntu；本脚本不写时钟参数或运行代理。',
  source_file: path.basename(sourcePath), source_sha256: sha(source), maintenance_source: source,
  prior_evidence: relative(priorPath), prior_evidence_sha256: sha(fs.readFileSync(priorPath)),
  steps: [], restoration: { docker: 'not_started', ubuntu: 'not_started' },
  proxy: { status: 'not_run', reason: '后续须核对根控制通道和计时门槛' },
};
const evidencePath = path.join(root, 'docs/验收证据/story-2-2-wsl-recovery-' + report.recorded_at.replace(/[:.]/g, '-') + '.json');
if (fs.existsSync(evidencePath) || fs.existsSync(livePath)) throw new Error('运行记录已存在');
const progress = (stage, details = {}) => {
  const event = { at: new Date().toISOString(), stage, ...details };
  report.steps.push(event);
  fs.writeFileSync(livePath, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify(event));
};
async function command(file, args, timeoutMs = 15000) {
  const started = performance.now();
  const child = spawn(file, args, { cwd: root, windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'] });
  const stdout = [], stderr = [];
  let failure;
  let length = 0;
  const timer = setTimeout(() => { failure = '命令超过宿主机预算'; child.kill(); }, timeoutMs);
  for (const [stream, chunks] of [[child.stdout, stdout], [child.stderr, stderr]]) stream.on('data', chunk => {
    chunks.push(chunk); length += chunk.length;
    if (length > 2 * 1024 * 1024) { failure = '命令输出超出预算'; child.kill(); }
  });
  child.stdin.on('error', error => { failure ??= error.message; });
  child.stdin.end();
  const result = await new Promise(resolve => {
    child.on('error', error => { failure = error.message; resolve({ code: null, signal: null }); });
    child.on('close', (code, signal) => resolve({ code, signal }));
  });
  clearTimeout(timer);
  const value = { file, args, ...result, elapsed_ms: performance.now() - started,
    stdout: decode(Buffer.concat(stdout)).trim(), stderr: decode(Buffer.concat(stderr)).trim() };
  if (failure || value.code !== 0) {
    const error = new Error(failure ?? file + ' 命令失败：' + value.code);
    error.result = value;
    throw error;
  }
  return value;
}
const docker = async args => (await command('docker', args)).stdout;
const distributions = async () => (await command('wsl.exe', ['--list', '--running', '--quiet'])).stdout.split(/\r?\n/).map(x => x.trim()).filter(Boolean).sort();
const bootId = async () => (await command('wsl.exe', ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'cat', '/proc/sys/kernel/random/boot_id'])).stdout;
async function containers() {
  const ids = (await docker(['ps', '-a', '--no-trunc', '--format', '{{.ID}}'])).split(/\r?\n/).filter(Boolean);
  if (!ids.length) return [];
  const format = '{"id":{{json .Id}},"name":{{json .Name}},"image":{{json .Image}},"status":{{json .State.Status}},"exit_code":{{json .State.ExitCode}},"started_at":{{json .State.StartedAt}},"finished_at":{{json .State.FinishedAt}},"restart_policy":{{json .HostConfig.RestartPolicy}},"mounts":{{json .Mounts}},"networks":{{json .NetworkSettings.Networks}}}';
  const rows = (await docker(['container', 'inspect', '--format', format, ...ids])).split(/\r?\n/).filter(Boolean).map(JSON.parse);
  for (const row of rows) {
    row.mounts.sort((a,b) => a.Destination.localeCompare(b.Destination));
    row.networks = Object.keys(row.networks ?? {}).sort();
  }
  return rows.sort((a,b) => a.id.localeCompare(b.id));
}
function files() {
  const names = new Set([...prior.preservation.files.map(x => x.path), ...prior.preservation.excluded_documents]);
  for (const name of fs.readdirSync(path.join(root, 'docs/验收证据')).filter(name => /^story-2-2-.*\.json$/.test(name))) names.add('docs/验收证据/' + name);
  return [...names].sort().map(file => ({ path: file, sha256: sha(fs.readFileSync(path.join(root,file))) }));
}
let stopAttempted = false;
let startAttempted = false;
let ubuntuAttempted = false;
async function startDocker() {
  startAttempted = true;
  progress('restoring_docker_desktop');
  report.restoration.docker_command = await command('docker', ['desktop', 'start', '--timeout', '120'], 125000);
  const deadline = performance.now() + 30000;
  while (true) {
    try { report.engine_after = await docker(['version', '--format', '{{.Server.Version}}']); break; }
    catch (error) { if (performance.now() >= deadline) throw error; await delay(1000); }
  }
  report.restoration.docker = 'restored';
  progress('docker_desktop_restored', { engine: report.engine_after });
}
async function startUbuntu() {
  ubuntuAttempted = true;
  report.restoration.ubuntu_command = await command('wsl.exe', ['-d','Ubuntu-24.04','-u','root','--','true'], 30000);
  report.restoration.ubuntu = 'restored';
  progress('ubuntu_restored');
}
try {
  report.baseline_commit = (await command('git', ['rev-parse','HEAD'])).stdout;
  if (report.baseline_commit !== prior.baseline_commit) throw new Error('Git 基线已变化');
  report.before = { distributions: await distributions(), containers: await containers(), files: files(), boot_id: await bootId() };
  if (JSON.stringify(report.before.distributions) !== JSON.stringify(['Ubuntu-24.04','docker-desktop'].sort())) throw new Error('运行发行版范围已变化');
  if (report.before.containers.length !== 7) throw new Error('既有容器数量变化');
  for (const row of report.before.containers) {
    const previous = prior.preservation.current_container_metadata.find(item => item.id === row.id);
    if (!previous || row.status !== 'exited' || !['no','unless-stopped'].includes(row.restart_policy.Name) ||
        JSON.stringify(row.restart_policy) !== JSON.stringify(previous.restart_policy)) throw new Error('既有容器状态或重启策略变化：' + row.name);
  }
  report.engine_before = await docker(['version','--format','{{.Server.Version}}']);
  report.compose_before = await docker(['compose','version','--short']);
  report.wsl_version = (await command('wsl.exe', ['--version'])).stdout;
  report.desktop_before = (await command('docker', ['desktop','status'])).stdout;
  if (!/running/i.test(report.desktop_before)) throw new Error('Docker Desktop 当前不是 running');
  const previousProxy = JSON.parse(fs.readFileSync(path.join(root,'docs/验收证据/story-2-2-proxy-timeouts-2026-09-12T03-25-47-619Z.json'),'utf8'));
  report.images = {};
  for (const [name, image] of Object.entries(previousProxy.images)) {
    const id = await docker(['image','inspect','--format','{{.Id}}',image.reference]);
    if (id !== image.id) throw new Error('候选镜像来源变化：' + name);
    report.images[name] = { reference:image.reference, id };
  }
  await new Promise((resolve,reject) => { const server=net.createServer(); server.once('error',reject); server.listen(3343,'127.0.0.1',()=>server.close(error=>error?reject(error):resolve())); });
  progress('preflight_passed', { containers:report.before.containers.length, files:report.before.files.length, distributions:report.before.distributions });
  stopAttempted = true;
  progress('stopping_docker_desktop');
  report.stop = await command('docker',['desktop','stop','--timeout','60'],65000);
  report.desktop_stopped = (await command('docker',['desktop','status'])).stdout;
  if (!/stopped/i.test(report.desktop_stopped)) throw new Error('未确认 Docker Desktop 正常停止');
  progress('stopping_wsl_once');
  report.shutdown = await command('wsl.exe',['--shutdown'],30000);
  report.distributions_stopped = await distributions();
  if (report.distributions_stopped.length) throw new Error('WSL 关闭后仍有运行的发行版');
  progress('wsl_stopped');
  await startDocker();
  await startUbuntu();
  report.after = { distributions: await distributions(), boot_id: await bootId(), containers: await containers() };
  if (JSON.stringify(report.after.distributions) !== JSON.stringify(report.before.distributions)) throw new Error('发行版未恢复到原运行范围');
  if (report.after.boot_id === report.before.boot_id) throw new Error('WSL 启动标识没有变化');
  if (report.engine_after !== report.engine_before) throw new Error('Engine 版本发生变化');
  report.status = 'restored';
} catch (error) {
  report.error = error.message;
  if (error.result) report.failed_command = error.result;
  progress('recovery_failed', { error:report.error });
} finally {
  if (stopAttempted && !startAttempted) {
    try { await startDocker(); }
    catch (error) { report.restoration.docker='failed'; report.restoration.docker_error=error.message; report.restoration.docker_failed_command=error.result; }
  }
  if (stopAttempted && !ubuntuAttempted) {
    try { await startUbuntu(); }
    catch (error) { report.restoration.ubuntu='failed'; report.restoration.ubuntu_error=error.message; }
  }
  if (report.before) {
    try {
      const after = await containers();
      report.preservation = {
        containers:report.before.containers.map(before=>{const current=after.find(row=>row.id===before.id);const changed=Object.keys(before).filter(key=>JSON.stringify(before[key])!==JSON.stringify(current?.[key]));return {id:before.id,name:before.name,unchanged:!changed.length,changed_fields:changed};}),
        new_container_ids:after.filter(row=>!report.before.containers.some(before=>before.id===row.id)).map(row=>row.id),
        files:report.before.files.map(before=>({path:before.path,sha256_before:before.sha256,sha256_after:sha(fs.readFileSync(path.join(root,before.path)))})),
      };
      report.preservation.passed=!report.preservation.new_container_ids.length&&report.preservation.containers.every(row=>row.unchanged)&&report.preservation.files.every(row=>row.sha256_before===row.sha256_after);
      if (!report.preservation.passed) report.status='failed';
    } catch (error) { report.preservation={passed:false,error:error.message}; report.status='failed'; }
  }
  report.finished_at=new Date().toISOString();
  fs.writeFileSync(evidencePath,JSON.stringify(report,null,2)+'\n',{flag:'wx'});
  progress('finished',{status:report.status,evidence:relative(evidencePath),preserved:report.preservation?.passed});
}
process.exitCode=report.status==='restored'?0:1;
